contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        address self = address(this);

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            reverted == (self != owner) &&
            (self != owner || (cBalAfter == 0 && depositsAfter == depositsBefore)) &&
            (self == owner || (cBalAfter == cBalBefore && depositsAfter == depositsBefore))
        );
    }

    receive() external payable {}
}

